import{_ as n,I as s,o,c as l,b6 as t,j as d,J as i,w as c}from"./chunks/framework.BUXTSoD9.js";const P=JSON.parse(`{"title":"Développement pratique d'un système de microservices pour l'e-commerce de produits frais","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"fr-fr/stage-2/assignments/simple-grocery-microservices/index.md"}`),p={name:"fr-fr/stage-2/assignments/simple-grocery-microservices/index.md"},u={style:{margin:"32px 0"}};function m(h,e,b,g,v,f){const a=s("StepBar"),r=s("ClientOnly");return o(),l("div",null,[e[0]||(e[0]=t('<h1 id="developpement-pratique-d-un-systeme-de-microservices-pour-l-e-commerce-de-produits-frais" tabindex="-1">Développement pratique d&#39;un système de microservices pour l&#39;e-commerce de produits frais <a class="header-anchor" href="#developpement-pratique-d-un-systeme-de-microservices-pour-l-e-commerce-de-produits-frais" aria-label="Permalink to “Développement pratique d&#39;un système de microservices pour l&#39;e-commerce de produits frais”">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to “Aperçu”">​</a></h2><p>Ce projet pratique vous demande de réaliser, à partir d&#39;un véritable PRD, un système de microservices pour l&#39;e-commerce de produits frais. Contrairement aux projets précédents basés sur un seul service, le backend de ce projet est découpé en plusieurs services indépendants selon le domaine métier, communiquant via une passerelle API unifiée. Vous apprendrez à concevoir les limites des services et à gérer la cohérence des données entre services.</p><p>Il s&#39;agit du projet pratique synthétique de l&#39;Étape 2. L&#39;architecture microservices est très courante en milieu professionnel. Une fois les principes de découpage des services et de routage par passerelle maîtrisés, vous serez en mesure de concevoir des systèmes backend plus complexes.</p><h2 id="prerequis" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequis" aria-label="Permalink to “Prérequis”">​</a></h2><p>Avant de commencer ce projet, vous devriez maîtriser les éléments suivants :</p><ul><li>Conception de pages frontales et utilisation de bibliothèques de composants (<a href="./../../frontend/ui-design/">Conception UI</a>, <a href="./../../frontend/modern-component-library/">Bibliothèque de composants moderne</a>)</li><li>Conception et développement d&#39;API backend (<a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface</a>)</li><li>Bases de données et Supabase (<a href="./../../backend/database-supabase/">Des bases de données à Supabase</a>)</li><li>Flux de travail Git et déploiement (<a href="./../../backend/git-workflow/">Git et GitHub</a>, <a href="./../../backend/zeabur-deployment/">Déployer une application web</a>)</li></ul><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to “Objectifs d&#39;apprentissage”">​</a></h2><p>Après avoir terminé ce projet, vous serez capable de :</p><ol><li>Lire un PRD et en extraire une liste de tâches de développement pour un système de microservices</li><li>Découper les limites des services par domaine métier (authentification, catalogue, inventaire, commandes)</li><li>Concevoir et implémenter le routage d&#39;une passerelle API</li><li>Gérer les problèmes inter-services tels que la décrémentation de stock et la cohérence des commandes</li><li>Effectuer des tests de bout en bout et livrer un prototype de microservices démontrable</li></ol><h2 id="presentation-du-projet" tabindex="-1">Présentation du projet <a class="header-anchor" href="#presentation-du-projet" aria-label="Permalink to “Présentation du projet”">​</a></h2><p>Le produit que vous allez construire est un système de microservices pour l&#39;e-commerce de produits frais :</p><table tabindex="0"><thead><tr><th>Sous-système</th><th>Responsabilité</th></tr></thead><tbody><tr><td><strong>Portail client</strong></td><td>Parcourir les produits, passer des commandes, consulter les commandes</td></tr><tr><td><strong>Portail gestion</strong></td><td>Gestion des produits, gestion des stocks, gestion des commandes</td></tr></tbody></table><p>Le backend est découpé en services par domaine métier :</p><table tabindex="0"><thead><tr><th>Service</th><th>Responsabilité</th></tr></thead><tbody><tr><td><strong>Passerelle API</strong></td><td>Point d&#39;entrée unique, routage, validation de l&#39;authentification</td></tr><tr><td><strong>Service d&#39;authentification</strong></td><td>Inscription, connexion, émission de JWT</td></tr><tr><td><strong>Service catalogue</strong></td><td>Gestion des informations produits</td></tr><tr><td><strong>Service inventaire</strong></td><td>Gestion des quantités en stock</td></tr><tr><td><strong>Service de commandes</strong></td><td>Création et gestion du statut des commandes</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Accès au PRD</p><p>Le document d&#39;exigences de ce projet se trouve sur GitHub : <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/fr-fr/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">Voir le PRD</a></p></div>',16)),d("div",u,[i(r,null,{default:c(()=>[i(a,{active:0,items:[{title:"Analyse des besoins",description:"Lire le PRD, clarifier la découpe des services, les API et la cohérence des données"},{title:"Construction du squelette",description:"Générer avec l'IA le squelette de la passerelle et des services de base"},{title:"Développement itératif",description:"Compléter les services un par un : auth, catalogue, inventaire, commandes"},{title:"Tests et mise en ligne",description:"Tests de bout en bout, déploiement et préparation de la démonstration"}]})]),_:1})]),e[1]||(e[1]=t(`<h2 id="partie-1-analyse-des-besoins" tabindex="-1">Partie 1 : Analyse des besoins <a class="header-anchor" href="#partie-1-analyse-des-besoins" aria-label="Permalink to “Partie 1 : Analyse des besoins”">​</a></h2><h3 id="_1-1-lire-le-prd" tabindex="-1">1.1 Lire le PRD <a class="header-anchor" href="#_1-1-lire-le-prd" aria-label="Permalink to “1.1 Lire le PRD”">​</a></h3><p>Ouvrez le document PRD et répondez aux questions suivantes :</p><ul><li>Comment les services sont-ils découpés ? Chaque service a-t-il sa propre base de données ?</li><li>Comment la passerelle API route-t-elle les requêtes vers les services concernés ?</li><li>Comment gérer la cohérence entre la décrémentation de stock et la création de commande ?</li><li>Quelles sont les fonctionnalités du MVP ?</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>Si les questions ci-dessus n&#39;ont pas de réponse claire, ne commencez pas à coder. Une mauvaise compréhension des besoins est la cause la plus fréquente de retour en arrière.</p></div><h3 id="_1-2-confirmer-l-architecture-du-systeme" tabindex="-1">1.2 Confirmer l&#39;architecture du système <a class="header-anchor" href="#_1-2-confirmer-l-architecture-du-systeme" aria-label="Permalink to “1.2 Confirmer l&#39;architecture du système”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  client[&quot;Client&quot;] --&gt; gateway[&quot;Passerelle API&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gateway --&gt; auth[&quot;Service d&#39;authentification&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gateway --&gt; catalog[&quot;Service catalogue&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gateway --&gt; inventory[&quot;Service inventaire&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gateway --&gt; order[&quot;Service de commandes&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  catalog --&gt; db1[&quot;DB Catalogue&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  inventory --&gt; db2[&quot;DB Inventaire&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; db3[&quot;DB Commandes&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  auth --&gt; db4[&quot;DB Auth&quot;]</span></span></code></pre></div><h2 id="partie-2-construction-du-squelette-du-projet" tabindex="-1">Partie 2 : Construction du squelette du projet <a class="header-anchor" href="#partie-2-construction-du-squelette-du-projet" aria-label="Permalink to “Partie 2 : Construction du squelette du projet”">​</a></h2><h3 id="_2-1-generer-les-pages-frontales" tabindex="-1">2.1 Générer les pages frontales <a class="header-anchor" href="#_2-1-generer-les-pages-frontales" aria-label="Permalink to “2.1 Générer les pages frontales”">​</a></h3><p>Prompt de référence :</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Veuillez générer, sur la base du PRD actuel, le squelette frontend d&#39;un système e-commerce de produits frais.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Exigences :</span></span>
<span class="line"><span>1. Portail client : liste des produits, panier, page de commande, historique des commandes</span></span>
<span class="line"><span>2. Portail gestion : gestion des produits, gestion des stocks, gestion des commandes</span></span>
<span class="line"><span>3. Générer d&#39;abord uniquement la structure des pages et des données fictives</span></span></code></pre></div><h3 id="_2-2-verifier-la-structure-des-pages" tabindex="-1">2.2 Vérifier la structure des pages <a class="header-anchor" href="#_2-2-verifier-la-structure-des-pages" aria-label="Permalink to “2.2 Vérifier la structure des pages”">​</a></h3><ul><li>[ ] Le portail client et le portail gestion sont-ils séparés ?</li><li>[ ] La liste des produits, le panier et les commandes fonctionnent-ils ?</li><li>[ ] Le portail gestion permet-il de gérer les produits et les stocks ?</li></ul><h2 id="partie-3-developpement-iteratif" tabindex="-1">Partie 3 : Développement itératif <a class="header-anchor" href="#partie-3-developpement-iteratif" aria-label="Permalink to “Partie 3 : Développement itératif”">​</a></h2><h3 id="_3-1-progresser-par-service" tabindex="-1">3.1 Progresser par service <a class="header-anchor" href="#_3-1-progresser-par-service" aria-label="Permalink to “3.1 Progresser par service”">​</a></h3><ol><li><strong>Passerelle API</strong> : Routage des requêtes, validation JWT</li><li><strong>Service d&#39;authentification</strong> : Inscription, connexion, émission de tokens</li><li><strong>Service catalogue</strong> : CRUD des produits, recherche</li><li><strong>Service inventaire</strong> : Suivi des stocks, décrémentation lors des commandes</li><li><strong>Service de commandes</strong> : Création de commandes, suivi du statut, historique</li></ol><h3 id="_3-2-points-d-attention-inter-services" tabindex="-1">3.2 Points d&#39;attention inter-services <a class="header-anchor" href="#_3-2-points-d-attention-inter-services" aria-label="Permalink to “3.2 Points d&#39;attention inter-services”">​</a></h3><ul><li><strong>Cohérence des stocks</strong> : Lorsqu&#39;une commande est créée, le stock doit être décrémenté de manière fiable</li><li><strong>Communication entre services</strong> : Utiliser des appels API synchrones ou des événements asynchrones</li><li><strong>Gestion des erreurs</strong> : Que se passe-t-il si le service d&#39;inventaire est indisponible lors d&#39;une commande ?</li></ul><h2 id="partie-4-tests-et-mise-en-ligne" tabindex="-1">Partie 4 : Tests et mise en ligne <a class="header-anchor" href="#partie-4-tests-et-mise-en-ligne" aria-label="Permalink to “Partie 4 : Tests et mise en ligne”">​</a></h2><h3 id="_4-1-tests-de-bout-en-bout" tabindex="-1">4.1 Tests de bout en bout <a class="header-anchor" href="#_4-1-tests-de-bout-en-bout" aria-label="Permalink to “4.1 Tests de bout en bout”">​</a></h3><ul><li>Parcourir les produits -&gt; Ajouter au panier -&gt; Commander -&gt; Vérifier la mise à jour du stock</li><li>Gestion : Ajouter un produit -&gt; Vérifier qu&#39;il apparaît côté client</li></ul><h3 id="_4-2-deploiement" tabindex="-1">4.2 Déploiement <a class="header-anchor" href="#_4-2-deploiement" aria-label="Permalink to “4.2 Déploiement”">​</a></h3><ul><li>Déployer chaque service indépendamment sur Zeabur / Railway / Render</li><li>Configurer la passerelle API pour router vers les services déployés</li><li>Utiliser des bases de données séparées ou Supabase avec des schémas distincts</li></ul><h2 id="livrables" tabindex="-1">Livrables <a class="header-anchor" href="#livrables" aria-label="Permalink to “Livrables”">​</a></h2><ul><li>[ ] Un lien de démonstration en ligne accessible</li><li>[ ] Un lien vers le dépôt de code source (avec README)</li><li>[ ] Le document PRD</li><li>[ ] Des captures d&#39;écran des pages principales</li><li>[ ] Une vidéo de démonstration de 60 secondes</li></ul><h2 id="criteres-d-evaluation" tabindex="-1">Critères d&#39;évaluation <a class="header-anchor" href="#criteres-d-evaluation" aria-label="Permalink to “Critères d&#39;évaluation”">​</a></h2><table tabindex="0"><thead><tr><th>Dimension</th><th>Exigences de base</th><th>Exigences avancées</th></tr></thead><tbody><tr><td>Services</td><td>L&#39;authentification et le catalogue fonctionnent</td><td>L&#39;inventaire et les commandes sont connectés</td></tr><tr><td>Passerelle</td><td>Les requêtes sont correctement routées</td><td>La validation JWT est opérationnelle</td></tr><tr><td>Technique</td><td>Chaque service peut être démarré indépendamment</td><td>La cohérence inter-services est gérée</td></tr><tr><td>Livraison</td><td>Le projet peut être exécuté et déployé</td><td>README clair et vidéo de démonstration</td></tr></tbody></table><h2 id="references" tabindex="-1">Références <a class="header-anchor" href="#references" aria-label="Permalink to “Références”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">Conception UI</a></li><li><a href="./../../frontend/modern-component-library/">Bibliothèque de composants moderne</a></li><li><a href="./../../backend/database-supabase/">Des bases de données à Supabase</a></li><li><a href="./../../backend/ai-interface-code/">Écriture de code d&#39;interface assistée par IA</a></li><li><a href="./../../backend/git-workflow/">Flux de travail Git et GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">Comment déployer une application web</a></li></ul>`,29))])}const y=n(p,[["render",m]]);export{P as __pageData,y as default};
